export { default as SoftAurora } from './SoftAurora.vue';
export { isSoftAuroraPreset, softAuroraPreset } from './soft-aurora-presets';
export type {
  SoftAuroraLook,
  SoftAuroraPreset,
  SoftAuroraProps,
} from './types';

import {
  SOFT_AURORA_FRAGMENT,
  SOFT_AURORA_MAX_PULSES,
  SOFT_AURORA_VERTEX,
} from './soft-aurora-shaders';
import type {
  SoftAuroraEngine,
  SoftAuroraProps,
  SoftAuroraSettings,
} from './types';

type Rgb = [number, number, number];

interface Pulse {
  x: number;
  y: number;
  age: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const smoother = (t: number) => {
  const x = clamp(t, 0, 1);
  return x * x * x * (x * (x * 6 - 15) + 10);
};

/** Parses `#rgb`, `#rrggbb` and `rgb()` colors into 0..1 channels. */
function parseSoftAuroraColor(value: string | undefined): Rgb | null {
  const text = String(value ?? '').trim();
  const hex = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(text);
  if (hex?.[1]) {
    const full =
      hex[1].length === 3
        ? hex[1].replace(/./g, (digit) => digit + digit)
        : hex[1];
    return [
      Number.parseInt(full.slice(0, 2), 16) / 255,
      Number.parseInt(full.slice(2, 4), 16) / 255,
      Number.parseInt(full.slice(4, 6), 16) / 255,
    ];
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(text);
  if (rgb) {
    return [
      clamp(Number.parseFloat(rgb[1] ?? '0') / 255, 0, 1),
      clamp(Number.parseFloat(rgb[2] ?? '0') / 255, 0, 1),
      clamp(Number.parseFloat(rgb[3] ?? '0') / 255, 0, 1),
    ];
  }
  return null;
}

/** Resolves props into the clamped settings the renderer reads. */
export function toSoftAuroraSettings(
  props: SoftAuroraProps,
): SoftAuroraSettings {
  return {
    speed: Math.max(0, props.speed ?? 0.6),
    scale: Math.max(0.01, props.scale ?? 1.5),
    brightness: Math.max(0, props.brightness ?? 1),
    color1: parseSoftAuroraColor(props.color1) ?? [0.969, 0.969, 0.969],
    color2: parseSoftAuroraColor(props.color2) ?? [0.882, 0, 1],
    noiseFrequency: Math.max(0.01, props.noiseFrequency ?? 2.5),
    noiseAmplitude: Math.max(0, props.noiseAmplitude ?? 1),
    bandHeight: props.bandHeight ?? 0.5,
    bandSpread: Math.max(0, props.bandSpread ?? 1),
    octaveDecay: Math.max(0, props.octaveDecay ?? 0.1),
    layerOffset: props.layerOffset ?? 0,
    colorSpeed: props.colorSpeed ?? 1,
    spectrum: clamp(props.spectrum ?? 1, 0, 1),
    tilt: (clamp(props.tilt ?? 0, -90, 90) * Math.PI) / 180,
    mouse: props.enableMouseInteraction ?? true,
    influence: Math.max(0, props.mouseInfluence ?? 0.25),
    clickPulse: props.clickPulse ?? true,
    intro: props.intro ?? true,
    light: props.lightMode ?? false,
    opacity: clamp(props.opacity ?? 1, 0, 1),
  };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(gl: WebGL2RenderingContext) {
  const vertex = compile(gl, gl.VERTEX_SHADER, SOFT_AURORA_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, SOFT_AURORA_FRAGMENT);
  const program = vertex && fragment ? gl.createProgram() : null;
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let index = 0; index < count; index++) {
    const info = gl.getActiveUniform(program, index);
    if (info) {
      uniforms[info.name.replace(/\[0\]$/, '')] = gl.getUniformLocation(
        program,
        info.name,
      );
    }
  }
  return { program, uniforms };
}

/**
 * One full-screen WebGL2 pass: two layers of 3D Perlin noise shape a band
 * that reaches toward the cursor and carries click pulses along it.
 */
export function createSoftAuroraEngine(
  canvas: HTMLCanvasElement,
  getSettings: () => SoftAuroraSettings,
  isReduced: () => boolean,
  skipIntro: boolean,
): SoftAuroraEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  const shader = gl ? link(gl) : null;
  if (!gl || !shader) return null;

  const vao = gl.createVertexArray();
  const size = { width: 1, height: 1 };
  const pointer = { x: 0.5, y: 0.5, inside: false };
  const mouse = { x: 0.5, y: 0.5, presence: 0 };
  const pulses: Pulse[] = [];
  const pulseData = new Float32Array(SOFT_AURORA_MAX_PULSES * 4);
  let flow = 0;
  let hue = 0;
  let opening = getSettings().intro && !isReduced() && !skipIntro ? 0 : 1;
  let last = 0;
  const u = (name: string) => shader.uniforms[name] ?? null;

  const resize = (cssWidth: number, cssHeight: number) => {
    const s = getSettings();
    const width = Math.max(1, cssWidth);
    const height = Math.max(1, cssHeight);
    const ratio = clamp(0.35 + 0.04 * s.noiseFrequency * s.scale, 0.5, 1);
    const w = Math.max(1, Math.round(width * ratio));
    const h = Math.max(1, Math.round(height * ratio));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
    }
    size.width = width;
    size.height = height;
  };

  const frame = (now: number) => {
    if (gl.isContextLost()) return false;
    const s = getSettings();
    const dt = last ? clamp((now - last) / 1000, 0, 0.05) : 0;
    last = Math.max(last, now);
    const pace = isReduced() ? 0.35 : 1;
    flow += dt * s.speed * pace;
    hue += dt * s.speed * s.colorSpeed * pace;
    if (opening < 1) opening = Math.min(1, opening + dt / 2);

    const tracking = s.mouse && pointer.inside;
    const follow = 1 - Math.exp(-dt / 0.325);
    mouse.x += ((tracking ? pointer.x : 0.5) - mouse.x) * follow;
    mouse.y += ((tracking ? pointer.y : 0.5) - mouse.y) * follow;
    mouse.presence +=
      ((tracking ? 1 : 0) - mouse.presence) *
      (1 - Math.exp(-dt / (tracking ? 0.45 : 0.8)));

    for (let index = pulses.length - 1; index >= 0; index--) {
      const pulse = pulses[index];
      if (!pulse) continue;
      pulse.age += dt;
      if (pulse.age >= 2.6) pulses.splice(index, 1);
    }
    pulseData.fill(0);
    pulses.forEach((pulse, index) => {
      pulseData[index * 4] = pulse.x;
      pulseData[index * 4 + 1] = pulse.y;
      pulseData[index * 4 + 2] =
        smoother(pulse.age / 0.18) * (1 - smoother((pulse.age - 0.18) / 2.42));
      pulseData[index * 4 + 3] = pulse.age;
    });

    const eased = 1 - Math.pow(1 - opening, 3);
    const aspect = size.width / size.height;
    const strength = Math.min(1, s.influence * 4) * mouse.presence;
    const drift = s.mouse ? s.influence : 0;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(shader.program);
    gl.bindVertexArray(vao);
    gl.uniform2f(u('uResolution'), canvas.width, canvas.height);
    gl.uniform1f(u('uFlow'), flow);
    gl.uniform1f(u('uHue'), hue);
    gl.uniform1f(u('uScale'), s.scale);
    gl.uniform1f(u('uBrightness'), s.brightness);
    gl.uniform3f(u('uColor1'), s.color1[0], s.color1[1], s.color1[2]);
    gl.uniform3f(u('uColor2'), s.color2[0], s.color2[1], s.color2[2]);
    gl.uniform1f(u('uNoiseFreq'), s.noiseFrequency);
    gl.uniform1f(u('uNoiseAmp'), s.noiseAmplitude);
    gl.uniform1f(u('uBandHeight'), s.bandHeight);
    gl.uniform1f(u('uBandSpread'), s.bandSpread);
    gl.uniform1f(u('uOctaveDecay'), s.octaveDecay);
    gl.uniform1f(u('uLayerOffset'), s.layerOffset);
    gl.uniform2f(u('uShift'), (mouse.x - 0.5) * drift, (mouse.y - 0.5) * drift);
    gl.uniform4f(u('uCursor'), mouse.x * aspect, mouse.y, strength, 0);
    gl.uniform4fv(u('uPulses'), pulseData);
    gl.uniform1f(u('uSpectrum'), s.spectrum);
    gl.uniform1f(u('uTilt'), s.tilt);
    gl.uniform3f(
      u('uIntro'),
      smoother(opening / 0.7),
      1 + 3 * (1 - eased) * (1 - eased),
      0.25 + 0.75 * eased,
    );
    gl.uniform1f(u('uLightMode'), s.light ? 1 : 0);
    gl.uniform1f(u('uOpacity'), s.opacity);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    const settling =
      Math.abs(mouse.x - (tracking ? pointer.x : 0.5)) > 1e-4 ||
      Math.abs(mouse.y - (tracking ? pointer.y : 0.5)) > 1e-4 ||
      Math.abs((tracking ? 1 : 0) - mouse.presence) > 1e-3 ||
      pulses.length > 0;
    return s.speed > 0 || opening < 1 || settling;
  };

  const pointerMove = (x: number, y: number, inside: boolean) => {
    pointer.x = x / Math.max(1, size.width);
    pointer.y = 1 - y / Math.max(1, size.height);
    pointer.inside = inside;
  };

  const pulse = (x: number, y: number) => {
    if (!getSettings().clickPulse || isReduced()) return false;
    const aspect = size.width / size.height;
    pulses.push({
      x: (x / Math.max(1, size.width)) * aspect,
      y: 1 - y / Math.max(1, size.height),
      age: 0,
    });
    if (pulses.length > SOFT_AURORA_MAX_PULSES) pulses.shift();
    return true;
  };

  const dispose = () => {
    if (gl.isContextLost()) return;
    gl.deleteVertexArray(vao);
    gl.deleteProgram(shader.program);
  };

  return {
    frame,
    resize,
    pointerMove,
    pulse,
    pointerLeave: () => {
      pointer.inside = false;
    },
    resetClock: () => {
      last = 0;
    },
    dispose,
  };
}

import type { SoftAuroraLook, SoftAuroraPreset } from './types';

const LOOK: SoftAuroraLook = {
  color1: '#f7f7f7',
  color2: '#e100ff',
  spectrum: 1,
  speed: 0.6,
  colorSpeed: 1,
  scale: 1.5,
  brightness: 1,
  noiseFrequency: 2.5,
  noiseAmplitude: 1,
  bandHeight: 0.5,
  bandSpread: 1,
  tilt: 0,
  octaveDecay: 0.1,
  layerOffset: 0,
};

const PRESETS: Record<SoftAuroraPreset, Partial<SoftAuroraLook>> = {
  classic: {},
  borealis: {
    color1: '#3EE59A',
    color2: '#22B8D3',
    spectrum: 0.2,
    bandHeight: 0.55,
    noiseAmplitude: 1.6,
    brightness: 0.8,
  },
  dusk: {
    color1: '#FFB86B',
    color2: '#FF5C8A',
    spectrum: 0.35,
    bandHeight: 0.38,
  },
  mono: {
    color1: '#E4E4E7',
    color2: '#71717A',
    spectrum: 0,
    brightness: 0.7,
  },
  ribbon: { tilt: -14, noiseAmplitude: 2.2, bandSpread: 1.3, scale: 1.2 },
  halo: { bandSpread: 0.55, brightness: 1.2, noiseFrequency: 1.5 },
  calm: { speed: 0.25, colorSpeed: 0.4, noiseAmplitude: 0.6 },
};

const LIGHT_SWAP: Partial<Record<SoftAuroraPreset, Partial<SoftAuroraLook>>> = {
  mono: { color1: '#52525B', color2: '#A1A1AA' },
};

/** The look of one of the demo presets. `light` swaps colors that vanish on light pages. */
export function softAuroraPreset(
  name: SoftAuroraPreset,
  light = false,
): SoftAuroraLook {
  return {
    ...LOOK,
    ...PRESETS[name],
    ...(light ? LIGHT_SWAP[name] : undefined),
  };
}

export function isSoftAuroraPreset(value: unknown): value is SoftAuroraPreset {
  return typeof value === 'string' && value in PRESETS;
}

export const SOFT_AURORA_MAX_PULSES = 4;

export const SOFT_AURORA_VERTEX = `#version 300 es
const vec2 corners[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
void main() {
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}`;

export const SOFT_AURORA_FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uFlow;
uniform float uHue;
uniform float uScale;
uniform float uBrightness;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform float uNoiseFreq;
uniform float uNoiseAmp;
uniform float uBandHeight;
uniform float uBandSpread;
uniform float uOctaveDecay;
uniform float uLayerOffset;
uniform vec2 uShift;
uniform vec4 uCursor;
uniform vec4 uPulses[${SOFT_AURORA_MAX_PULSES}];
uniform float uSpectrum;
uniform float uTilt;
uniform vec3 uIntro;
uniform float uLightMode;
uniform float uOpacity;
out vec4 fragColor;

#define TAU 6.28318

vec3 gradientHash(vec3 p) {
  p = vec3(
    dot(p, vec3(127.1, 311.7, 234.6)),
    dot(p, vec3(269.5, 183.3, 198.3)),
    dot(p, vec3(169.5, 283.3, 156.9))
  );
  vec3 h = fract(sin(p) * 43758.5453123);
  float phi = acos(2.0 * h.x - 1.0);
  float theta = TAU * h.y;
  return vec3(cos(theta) * sin(phi), sin(theta) * cos(phi), cos(phi));
}

float quinticSmooth(float t) {
  float t2 = t * t;
  float t3 = t * t2;
  return 6.0 * t3 * t2 - 15.0 * t2 * t2 + 10.0 * t3;
}

vec3 cosineGradient(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  return a + b * cos(TAU * (c * t + d));
}

float perlin3D(float amplitude, float frequency, float px, float py, float pz) {
  float x = px * frequency;
  float y = py * frequency;

  float fx = floor(x);
  float fy = floor(y);
  float fz = floor(pz);
  float cx = ceil(x);
  float cy = ceil(y);
  float cz = ceil(pz);

  vec3 g000 = gradientHash(vec3(fx, fy, fz));
  vec3 g100 = gradientHash(vec3(cx, fy, fz));
  vec3 g010 = gradientHash(vec3(fx, cy, fz));
  vec3 g110 = gradientHash(vec3(cx, cy, fz));
  vec3 g001 = gradientHash(vec3(fx, fy, cz));
  vec3 g101 = gradientHash(vec3(cx, fy, cz));
  vec3 g011 = gradientHash(vec3(fx, cy, cz));
  vec3 g111 = gradientHash(vec3(cx, cy, cz));

  float d000 = dot(g000, vec3(x - fx, y - fy, pz - fz));
  float d100 = dot(g100, vec3(x - cx, y - fy, pz - fz));
  float d010 = dot(g010, vec3(x - fx, y - cy, pz - fz));
  float d110 = dot(g110, vec3(x - cx, y - cy, pz - fz));
  float d001 = dot(g001, vec3(x - fx, y - fy, pz - cz));
  float d101 = dot(g101, vec3(x - cx, y - fy, pz - cz));
  float d011 = dot(g011, vec3(x - fx, y - cy, pz - cz));
  float d111 = dot(g111, vec3(x - cx, y - cy, pz - cz));

  float sx = quinticSmooth(x - fx);
  float sy = quinticSmooth(y - fy);
  float sz = quinticSmooth(pz - fz);

  float lx00 = mix(d000, d100, sx);
  float lx10 = mix(d010, d110, sx);
  float lx01 = mix(d001, d101, sx);
  float lx11 = mix(d011, d111, sx);

  float ly0 = mix(lx00, lx10, sy);
  float ly1 = mix(lx01, lx11, sy);

  return amplitude * mix(ly0, ly1, sz);
}

float auroraGlow(float t, vec2 uv, float bend) {
  float noiseVal = 0.0;
  float freq = uNoiseFreq;
  float amp = uNoiseAmp;
  vec2 samplePos = uv * uScale;

  for (float i = 0.0; i < 3.0; i += 1.0) {
    noiseVal += perlin3D(amp, freq, samplePos.x, samplePos.y, t);
    amp *= uOctaveDecay;
    freq *= 2.0;
  }

  float yBand = uv.y * 10.0 - (uBandHeight + bend) * 10.0;
  return 0.3 * max(exp(uBandSpread * (1.0 - 1.1 * uIntro.y * abs(noiseVal * uIntro.z + yBand))), 0.0);
}

vec2 turn(vec2 p, vec2 center) {
  float c = cos(uTilt);
  float s = sin(uTilt);
  vec2 d = p - center;
  return center + vec2(c * d.x - s * d.y, s * d.x + c * d.y);
}

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution.xy;
  vec2 center = vec2(0.5 * uResolution.x / uResolution.y, 0.5);
  vec2 screen = turn(gl_FragCoord.xy / uResolution.y, center);
  vec2 cursor = turn(uCursor.xy, center);
  vec2 field = screen + uShift;
  float t = 0.4 * uFlow;

  float reach = exp(-pow((screen.x - cursor.x) / 0.32, 2.0)) * uCursor.z;
  float gap = cursor.y + uShift.y - uBandHeight;
  float near = exp(-gap * gap / 0.16);
  float bend = reach * gap * near * 0.55;

  float pulse = 0.0;
  for (int i = 0; i < ${SOFT_AURORA_MAX_PULSES}; i++) {
    vec4 wave = uPulses[i];
    if (wave.z <= 0.0) continue;
    float x = (abs(screen.x - turn(wave.xy, center).x) - wave.w * 0.55) / (0.1 + wave.w * 0.06);
    pulse += wave.z * exp(-x * x);
  }
  float boost = (1.0 + reach * near * 0.25 + pulse * 0.65) * uIntro.x;

  float glow1 = auroraGlow(t, field, bend) * boost;
  float glow2 = auroraGlow(t + uLayerOffset, field, bend) * boost;
  vec3 gradient1 = mix(vec3(1.0), cosineGradient(uv.x + uHue * 0.2, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.3, 0.20, 0.20)), uSpectrum);
  vec3 gradient2 = mix(vec3(1.0), cosineGradient(uv.x + uHue * 0.1, vec3(0.5), vec3(0.5), vec3(2.0, 1.0, 0.0), vec3(0.5, 0.20, 0.25)), uSpectrum);

  vec3 col = 0.99 * glow1 * gradient1 * uColor1;
  col += 0.99 * glow2 * gradient2 * uColor2;
  col *= uBrightness;

  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;
  if (uLightMode > 0.5) {
    float energy = max(col.r, max(col.g, col.b));
    vec3 hue = clamp(col / max(energy, 1e-4), 0.0, 1.0);
    vec3 average = (glow1 * uColor1 + glow2 * uColor2) / max(glow1 + glow2, 1e-4);
    float top = max(average.r, max(average.g, average.b));
    float spread = top - min(average.r, min(average.g, average.b));
    float core = smoothstep(0.55, 1.6, energy);
    float depth = 1.25 + 0.45 * core;
    vec3 tint = mix(average * 0.82, pow(average / max(top, 1e-4), vec3(depth + 0.6)), smoothstep(0.04, 0.2, spread));
    float vivid = smoothstep(0.12, 0.55, 1.0 - min(hue.r, min(hue.g, hue.b))) * smoothstep(0.04, 0.2, spread);
    vec3 ink = mix(tint, pow(hue, vec3(depth)), vivid) * mix(0.93, 0.8, core);
    float density = 0.88 * (1.0 - exp(-1.9 * pow(energy, 1.7)));
    density = clamp(density * uOpacity + grain, 0.0, 1.0);
    fragColor = vec4(ink * density, density);
  } else {
    float alpha = clamp(length(col), 0.0, 1.0);
    vec3 color = clamp(col, 0.0, 1.0);
    fragColor = vec4(clamp(color * alpha + grain, 0.0, alpha) * uOpacity, alpha * uOpacity);
  }
}`;

export type SoftAuroraPreset =
  | 'classic'
  | 'borealis'
  | 'dusk'
  | 'mono'
  | 'ribbon'
  | 'halo'
  | 'calm';

export interface SoftAuroraProps {
  /** Overall animation speed. */
  speed?: number;
  /** Scale of the noise that shapes the band. */
  scale?: number;
  /** Overall brightness. */
  brightness?: number;
  /** Tint of the first aurora layer. Hex or rgb() color. */
  color1?: string;
  /** Tint of the second aurora layer. Hex or rgb() color. */
  color2?: string;
  /** How tightly the band ripples. */
  noiseFrequency?: number;
  /** How far the band waves up and down. */
  noiseAmplitude?: number;
  /** Vertical position of the band, from 0 at the bottom to 1 at the top. */
  bandHeight?: number;
  /** How tight and bright the band is. Lower values spread it into a wide, soft glow. */
  bandSpread?: number;
  /** How much fine ripple sits on top of the large waves. */
  octaveDecay?: number;
  /** Shifts the second layer in time so the two separate. */
  layerOffset?: number;
  /** How fast the colors drift along the band. */
  colorSpeed?: number;
  /** How much of the shifting rainbow shows through the tints, from 0 to 1. */
  spectrum?: number;
  /** Tilts the band by this many degrees, from -90 to 90. */
  tilt?: number;
  /** The aurora drifts with the cursor and reaches toward it when it comes close. */
  enableMouseInteraction?: boolean;
  /** Strength of the cursor drift and reach. */
  mouseInfluence?: number;
  /** Clicking sends a soft pulse of light along the band. */
  clickPulse?: boolean;
  /** The band starts as a thin line and blooms in on mount. */
  intro?: boolean;
  /** Prints the aurora as soft colored ink so it sits on light pages. */
  lightMode?: boolean;
  /** Overall opacity, from 0 to 1. */
  opacity?: number;
  class?: string;
}

export interface SoftAuroraSettings {
  speed: number;
  scale: number;
  brightness: number;
  color1: [number, number, number];
  color2: [number, number, number];
  noiseFrequency: number;
  noiseAmplitude: number;
  bandHeight: number;
  bandSpread: number;
  octaveDecay: number;
  layerOffset: number;
  colorSpeed: number;
  spectrum: number;
  tilt: number;
  mouse: boolean;
  influence: number;
  clickPulse: boolean;
  intro: boolean;
  light: boolean;
  opacity: number;
}

/** The props a demo preset sets. */
export interface SoftAuroraLook {
  color1: string;
  color2: string;
  spectrum: number;
  speed: number;
  colorSpeed: number;
  scale: number;
  brightness: number;
  noiseFrequency: number;
  noiseAmplitude: number;
  bandHeight: number;
  bandSpread: number;
  tilt: number;
  octaveDecay: number;
  layerOffset: number;
}

export interface SoftAuroraEngine {
  /** Advances one frame. Returns false once nothing is moving, so the loop can stop. */
  frame: (now: number) => boolean;
  /** Resizes the canvas to the container (the resolution follows the noise detail). */
  resize: (width: number, height: number) => void;
  /** Pointer position in px relative to the container. */
  pointerMove: (x: number, y: number, inside: boolean) => void;
  /** Sends a pulse from a point in px relative to the container. Returns true if one was sent. */
  pulse: (x: number, y: number) => boolean;
  pointerLeave: () => void;
  resetClock: () => void;
  dispose: () => void;
}
